// routes/CRM/phase12Routes.js
//
// Phase 12 — Invoice, Payment, Credit Note, GSTR, AR Aging
// All routes require authentication middleware (protect) passed from app.js.
// Role checks (Manager, Accounts) are noted in comments.
//
// PDF GENERATION: All PDFs are generated by the frontend.
// Backend returns structured JSON data including:
