/**
 * @swagger
 * /api/invoices/{id}:
 *   get:
 *     summary: Get complete invoice details by ID
 *     tags: ["Phase 12 — Invoice"]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *         description: Invoice ObjectId
 *     responses:
 *       200:
 *         description: Complete invoice with items, HSN breakup, payment history
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 success:
 *                   type: boolean
 *                 data:
 *                   $ref: '#/components/schemas/Invoice'
 *       404:
 *         description: Invoice not found
 *       401:
 *         description: Unauthorized
 */
router.get('/:id', getInvoiceById);

/**
 * @swagger
 * /api/invoices/{id}/pdf-data:
 *   get:
 *     summary: Get invoice data for frontend PDF generation
 *     description: |
 *       Returns all necessary data for the frontend to generate a professional
 *       GST invoice PDF including:
 *       - Company letterhead details
 *       - Customer details
 *       - Line items with HSN, GST breakup
 *       - QR code data URL (if e-Invoice generated)
 *       - Pre-computed amount in words
 *       - Bank details
 *     tags: ["Phase 12 — Invoice"]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *         description: Invoice ObjectId
 *     responses:
 *       200:
 *         description: JSON data ready for frontend PDF rendering
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 success:
 *                   type: boolean
 *                 data:
 *                   type: object
 *                   properties:
 *                     invoice:
 *                       $ref: '#/components/schemas/Invoice'
 *                     company:
 *                       type: object
 *                     qr_code_data_url:
 *                       type: string
 *                       description: Base64 QR code image for e-Invoice
 *                     bank_details:
 *                       type: object
 *       404:
 *         description: Invoice not found
 */
router.get('/:id/pdf-data', getInvoiceDataForPdf);

/**
 * @swagger
 * /api/invoices/{id}/submit-irn:
 *   post:
 *     summary: Submit invoice to e-Invoice portal (IRP) for IRN generation
 *     tags: ["Phase 12 — e-Invoice"]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *         description: Invoice ObjectId
 *     responses:
 *       200:
 *         description: IRN generated successfully
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 success:
 *                   type: boolean
 *                 message:
 *                   type: string
 *                 data:
 *                   type: object
 *                   properties:
 *                     invoice_no:
 *                       type: string
 *                     irn:
 *                       type: string
 *                     ack_no:
 *                       type: string
 *                     irn_generated_at:
 *                       type: string
 *                       format: date-time
 *                     irn_cancellable:
 *                       type: boolean
 *                     hours_since_irn:
 *                       type: number
 *       400:
 *         description: Cannot submit (status invalid or IRN already exists)
 *       502:
 *         description: IRP API error
 */
router.post('/:id/submit-irn', submitIRN);

/**
 * @swagger
 * /api/invoices/{id}/cancel-irn:
 *   delete:
 *     summary: Cancel e-Invoice IRN (within 24 hours only)
 *     tags: ["Phase 12 — e-Invoice"]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *         description: Invoice ObjectId
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - cancel_reason
 *             properties:
 *               cancel_reason:
 *                 type: string
 *                 example: "Data entry mistake in customer GSTIN"
 *     responses:
 *       200:
 *         description: IRN cancelled successfully
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 success:
 *                   type: boolean
 *                 message:
 *                   type: string
 *                 data:
 *                   type: object
 *                   properties:
 *                     invoice_no:
 *                       type: string
 *                     irn:
 *                       type: string
 *                     irn_cancelled_at:
 *                       type: string
 *                       format: date-time
 *       400:
 *         description: Cannot cancel (beyond 24h or no IRN)
 *       401:
 *         description: Unauthorized
 */
router.delete('/:id/cancel-irn', cancelIRN);

/**
 * @swagger
 * /api/invoices/{id}/send:
 *   post:
 *     summary: Send invoice to customer email
 *     description: |
 *       Returns invoice data including email status.
 *       Frontend can generate PDF and send via email using the returned data.
 *       If SMTP is configured, email is sent automatically.
 *       Returns email_sent flag and invoice data.
 *     tags: ["Phase 12 — Invoice"]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *         description: Invoice ObjectId
 *     requestBody:
 *       required: false
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             properties:
 *               email:
 *                 type: string
 *                 format: email
 *                 description: Override recipient email (optional)
 *     responses:
 *       200:
 *         description: Invoice sent (or email queued)
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 success:
 *                   type: boolean
 *                 message:
 *                   type: string
 *                 data:
 *                   type: object
 *                   properties:
 *                     invoice:
 *                       $ref: '#/components/schemas/Invoice'
 *                     email_sent:
 *                       type: boolean
 *                     sent_to:
 *                       type: string
 *                     qr_code_data_url:
 *                       type: string
 *       400:
 *         description: Cannot send cancelled invoice
 *       404:
 *         description: Invoice not found
 */
router.post('/:id/send', sendInvoice);
router.put('/:id/confirm', confirmInvoice);
router.put('/:id/cancel', cancelInvoice);

/**
 * @swagger
 * /api/invoices/{id}/apply-advance:
 *   put:
 *     summary: Apply customer advance balance to an invoice
 *     tags: ["Phase 12 — Payment"]
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *         description: Invoice ObjectId
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - advance_id
 *               - amount
 *             properties:
 *               advance_id:
 *                 type: string
 *                 description: CustomerAdvance ObjectId
 *               amount:
 *                 type: number
 *                 minimum: 0.01
 *     responses:
 *       200:
 *         description: Advance applied successfully
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 success:
 *                   type: boolean
 *                 message:
 *                   type: string
 *                 data:
 *                   type: object
 *                   properties:
 *                     invoice_no:
 *                       type: string
 *                     advance_no:
 *                       type: string
 *                     applied_amount:
 *                       type: number
 *                     invoice_balance_due:
 *                       type: number
 *                     advance_balance:
 *                       type: number
 *       400:
 *         description: Invalid advance or insufficient balance
 *       404:
 *         description: Invoice or advance not found
 */
router.put('/:id/apply-advance', applyAdvanceToInvoice);

module.exports = router;

